    PrevalidateReusableKeys = true,
    SaveReusableKey = true,
}

local environment = (getgenv and getgenv()) or _G
local KeySystem = {}

local sdk
function KeySystem.getSdk()
    if sdk then return sdk end
    local source = game:HttpGet("https://jnkie.com/sdk/library.lua")
    local chunk = loadstring(source)
    assert(chunk, "SDK compilation failed")
    local library = chunk()
    assert(type(library) == "table", "Invalid SDK")
    assert(type(library.get_key_link) == "function", "SDK has no get_key_link")
    assert(type(library.check_key) == "function", "SDK has no check_key")
    library.service = Config.Service
    library.identifier = tostring(Config.Identifier)
    library.provider = Config.Provider
    library.script_id = Config.ScriptId
    sdk = library
    return library
end

function KeySystem.errorMessage(code)
    local messages = {
        KEY_INVALID = "Key expired or invalid. Try again.",
        KEY_EXPIRED = "Key expired or invalid. Try again.",
        KEY_INVALIDATED = "This key was disabled.",
        ALREADY_USED = "This one-time key has already been used.",
        HWID_BANNED = "Access is blocked for this device.",
        HWID_MISMATCH = "This key is linked to a different device.",
        SERVICE_NOT_FOUND = "The key service is unavailable. Contact support.",
        SERVICE_MISMATCH = "This key belongs to another service.",
        PREMIUM_REQUIRED = "A premium key is required.",
        RATE_LIMITTED = "Too many requests. Please wait and try again.",
        ERROR = "Unable to connect. Please try again.",
        INVALID_RESPONSE = "The service returned an unexpected response.",
    }
    code = tostring(code or "ERROR")
    if code:match("^http 429") then return messages.RATE_LIMITTED end
    if code:match("^http %d+") then return "The key service is unavailable. Try again shortly." end
    return messages[code] or "Unable to complete the request. Please try again."
end

function KeySystem.checkReusableKey(key)
    local ok, result = pcall(function() return KeySystem.getSdk().check_key(key) end)
    if not ok then return false, KeySystem.errorMessage("ERROR"), "ERROR" end
    if type(result) ~= "table" or type(result.valid) ~= "boolean" then
        return false, KeySystem.errorMessage("INVALID_RESPONSE"), "INVALID_RESPONSE"
    end
    if result.valid then return true end
    return false, KeySystem.errorMessage(result.error), tostring(result.error or "ERROR")
end

function KeySystem.requestKeyLink()
    local ok, link, err = pcall(function() return KeySystem.getSdk().get_key_link() end)
    if not ok then return nil, KeySystem.errorMessage("ERROR") end
    if not link then return nil, KeySystem.errorMessage(err) end
    if type(link) ~= "string" then return nil, KeySystem.errorMessage("INVALID_RESPONSE") end
    link = link:match("^%s*(.-)%s*$")
    if not link:match("^https://%S+$") then
        return nil, KeySystem.errorMessage("INVALID_RESPONSE")
    end
    return link
end

local HttpService = game:GetService("HttpService")
local cachePath = "Anerial/Keys/junkie-" .. tostring(Config.Identifier) .. "-" .. Config.ScriptId:gsub("[^%w%-]", "") .. ".json"
function KeySystem.readSavedKey()
    if not Config.SaveReusableKey or type(isfile) ~= "function" or type(readfile) ~= "function" then return nil end
    local ok, saved = pcall(function()
        if not isfile(cachePath) then return nil end
        return HttpService:JSONDecode(readfile(cachePath))
    end)
    if not ok or type(saved) ~= "table" then return nil end
    if saved.Service ~= Config.Service or tostring(saved.Identifier) ~= tostring(Config.Identifier)
        or saved.ScriptId ~= Config.ScriptId or type(saved.Key) ~= "string" then return nil end
    local key = saved.Key:match("^%s*(.-)%s*$")
    return key ~= "" and key or nil
end
function KeySystem.saveKey(key)
    if not Config.SaveReusableKey or not Config.PrevalidateReusableKeys then return false end
    if type(writefile) ~= "function" or type(isfolder) ~= "function" or type(makefolder) ~= "function" then return false end
    return pcall(function()
        if not isfolder("Anerial") then makefolder("Anerial") end
        if not isfolder("Anerial/Keys") then makefolder("Anerial/Keys") end
        writefile(cachePath, HttpService:JSONEncode({Key = key, Service = Config.Service,
            Identifier = tostring(Config.Identifier), ScriptId = Config.ScriptId}))
    end)
end
function KeySystem.forgetSavedKey()
    if type(delfile) == "function" then
        local ok = pcall(delfile, cachePath)
        if ok then return end
    end
    if type(writefile) == "function" then pcall(writefile, cachePath, "{}") end
end
function KeySystem.isInvalidKey(code)
    return code == "KEY_INVALID" or code == "KEY_EXPIRED" or code == "KEY_INVALIDATED" or code == "ALREADY_USED"
end
