local function submitKey()
    if state.done or state.busy then return end
    local key = keyBox.Text:match("^%s*(.-)%s*$")
    if key == "" then setStatus("Paste your key first."); return end
    setBusy(true, "Please wait...")
    task.spawn(function()
        if Config.PrevalidateReusableKeys then
            local valid, err = KeySystem.checkReusableKey(key)
            if state.done then return end
            if not valid then setBusy(false, err); return end
        end
        if Config.Mode == "External" then
            local ok = pcall(KeySystem.getSdk)
            if state.done then return end
            if not ok then setBusy(false, KeySystem.errorMessage("ERROR")); return end
        end
        if not state.done then
            if Config.PrevalidateReusableKeys then KeySystem.saveKey(key) end
            finish(key)
        end
    end)
