function KeySystem.decodeLogoAsset(encoded)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local values = {}
    for index = 1, #alphabet do values[alphabet:byte(index)] = index - 1 end
    local output, accumulator, bits = {}, 0, 0
    for index = 1, #encoded do
        local value = values[encoded:byte(index)]
        if value then
            accumulator = bit32.bor(bit32.lshift(accumulator, 6), value)
            bits += 6
            if bits >= 8 then
                bits -= 8
                output[#output + 1] = string.char(bit32.band(bit32.rshift(accumulator, bits), 255))
                accumulator = bit32.band(accumulator, 2 ^ bits - 1)
            end
        end
    end
    return table.concat(output)
end
