    logoButton.ImageRectOffset = Vector2.zero
    logoButton:SetAttribute("GIFFrames", 40)
    local delays = {0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15, 0.15}
    local index, remaining = 1, delays[1]
    connect(game:GetService("RunService").Heartbeat, function(deltaTime)
        if state.done or not gui.Enabled then return end
        remaining -= deltaTime
        if remaining > 0 then return end
        local advances = 0
        repeat
            index = index % #delays + 1
            remaining += delays[index]
            advances += 1
        until remaining > 0 or advances >= #delays
        if remaining <= 0 then remaining = delays[index] end
        logoButton.ImageRectOffset = Vector2.new(((index - 1) % 8) * 128, math.floor((index - 1) / 8) * 114)
    end)
end)

gui.Parent = player:WaitForChild("PlayerGui")
resizeForScreen()
environment.SCRIPT_KEY = nil
environment.UI_CLOSED = false
while not state.done do completed.Event:Wait() end
completed:Destroy()
if environment.AnerialKeySystem ~= state then return end
if not state.selectedKey then
    environment.UI_CLOSED = true
    return
end
environment.SCRIPT_KEY = state.selectedKey
KeySystem.launchSelectedGame(state.selectedKey)

end
